    exact (srun_sound tm true true chb_0RB1LC_1LC1RA_1RA1LD_1RB0LC B0_0RB1LC_1LC1RA_1RA1LD_1RB0LC BB1_0RB1LC_1LC1RA_1RA1LD_1RB0LC 4 12
             run_boot_0RB1LC_1LC1RA_1RA1LD_1RB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
