    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB1LC_1LC1RA_1RA1LD_1RB0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1LC_1LC1RA_1RA1LD_1RB0LC
      with (l := [SWin 2]).
