    apply (fire_via_ovf_lift tm Cc lapil_0RB1LC_1LC1RA_1RA1LD_1RB0LC (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LC_1LC1RA_1RA1LD_1RB0LC [SWin 8; SCycL 2 0; SWin 2; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LC_1LC1RA_1RA1LD_1RB0LC
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1LC_1LC1RA_1RA1LD_1RB0LC
      with (l := [SWin 4]).
