Definition tm_0RB1LC_1RC1RA_1LA1LD_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S0 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LC_1RC1RA_1LA1LD_1RB0LC : list Instr := [(StB, S0)].
Definition tmw_0RB1LC_1RC1RA_1LA1LD_1RB0LC : TM := tm_wrap_trs tm_0RB1LC_1RC1RA_1LA1LD_1RB0LC pins_0RB1LC_1RC1RA_1LA1LD_1RB0LC.
Local Notation tm := tmw_0RB1LC_1RC1RA_1LA1LD_1RB0LC.

Definition Cc_0RB1LC_1RC1RA_1LA1LD_1RB0LC (p : positive) : cconf := (StA, (Ip p ++ [S0], S0, [S1;S1;S1])).
Local Notation Cc := Cc_0RB1LC_1RC1RA_1LA1LD_1RB0LC.

(** ** The certificate *)

Definition A0_0RB1LC_1RC1RA_1LA1LD_1RB0LC : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S1;S1] [] 0 0 []).
Definition A1_0RB1LC_1RC1RA_1LA1LD_1RB0LC : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S1;S1] [] 0 0 []).
Definition chi_0RB1LC_1RC1RA_1LA1LD_1RB0LC : list lstep := [SWin 8; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_int_0RB1LC_1RC1RA_1LA1LD_1RB0LC : srun tm false true chi_0RB1LC_1RC1RA_1LA1LD_1RB0LC A0_0RB1LC_1RC1RA_1LA1LD_1RB0LC = Some (A1_0RB1LC_1RC1RA_1LA1LD_1RB0LC, 4, 12).
