    apply (lap_of_run tm Cc true true cho_0RB1LD_1RC1RB_1LA0LD_0RB0LC B0_0RB1LD_1RC1RB_1LA0LD_0RB0LC B1_0RB1LD_1RC1RB_1LA0LD_0RB0LC 4 8 p j' [] []).
